from build_inputs import D,read
def n(v):return f"{v:,d}".replace(',',' ')
def pc(v):return f"{100*v:.3f}".replace('.',',')
def ci(v):return pc(v['delta'])+' ['+pc(v['ci'][0])+'; '+pc(v['ci'][1])+']'
def main():
    panels=read(D/'results.json')['panels'];s=panels['R49'];dev=panels['R48'];res=read(D/'resources.json');ab=read(D/'ablation-results.json')['panels'];m=read(D/'models.json')['transfer']['graph']
    names={'graph':'Обученная политика с файловыми связями','local':'Та же модель без файлового контекста','proposed':'Частота × стоимость (R48/R49)','lru_costhot':'Стоимостный hot-LRU','gdsf':'Пакетный GDSF','cost':'Только стоимость'}
    out=['# Когда стоит сохранить эмбеддинг по истории соседних фрагментов файла',
      f"На 179 состояниях из 68 репозиториев графовая политика при вместимости 31 вектор сэкономила **{n(s['arms']['proposed']['tokens'])} дополнительных входных токенов** относительно «частота × стоимость» и **{n(s['arms']['local']['tokens'])}** относительно той же модели без файлового контекста. Выигрыш в доле исходного входа — **{ci(s['arms']['proposed'])} п.п.** и **{ci(s['arms']['local'])} п.п.** соответственно. Оба заранее заданных критерия для этой панели выполнены. Проценты описывают объём повторного кодирования. [Первичный протокол](PROTOCOL_RU.md) · [Машинные результаты](results.json)",
      '## Что сохраняет метод',
      'После выдачи агенту известны текущий пул фрагментов и до 31 ранее оставленного вектора. С каждым точным ключом токенов хранится короткая запись о файле, диапазоне строк, давности и числе наблюдений за время резидентности. При записи алгоритм группирует фрагменты по файлу и отмечает, какие соседние диапазоны сохранились, появились или перестали встречаться в текущем пуле. По локальным признакам и этим связям логистическая регрессия оценивает вероятность повторного предъявления точного ключа в следующем запросе. Это маленький двудольный граф фрагментов и файлов, построенный только на посещённых источниках. Изменение пула может отражать поиск, а не правку файла. [Признаки и выбор](predict.py)',
      'Пусть для фрагмента i стоимость кодирования равна cᵢ, а вероятность его следующего предъявления равна pᵢ. При одинаковой ёмкости каждого вектора ожидаемая сумма сэкономленных токенов для набора S равна ∑ᵢ∈S cᵢpᵢ по линейности ожидания. Отсюда оптимальный набор для одношаговой задачи при известных вероятностях — 31 наибольшее произведение. Зависимость между будущими предъявлениями этому выводу не мешает. В эксперименте вероятности оцениваются по наблюдениям; у формулы нет гарантии многошаговой оптимальности или оптимальности задержки GPU.',
      '## Как исключена информация о будущем',
      f"Для разработки использованы 305 состояний из 103 репозиториев. Каждый разработческий прогноз получен моделью, обученной на других репозиториях по пяти фиксированным фолдам. Для внешнего по репозиториям переноса модель переобучалась один раз на {len(m['train_states'])} доступных обучающих переходах из {len(m['train_repos'])} репозиториев, {n(m['n_examples'])} бинарных примеров с учётом всех кандидатов записи. 68 репозиториев переноса полностью отделены от 103 разработческих. Во время обучения метка означает присутствие ключа в непосредственно следующем наблюдаемом пуле того же запуска. Во время оценки каждый алгоритм удерживает только собственных резидентов. Для cold-состояний экономия равна нулю; они входят в знаменатель. Обе части публичной SERBench Cal500 уже изучались в других сериях. [Переменные модели](models.json) · [Обучение и разбиение](study.py)",
      '## Экономия входных токенов',
      'Показаны парные 95% интервалы процентильного бутстрепа по целым репозиториям. Разность считается как дополнительная экономия исследуемой политики относительно метода в строке, делённая на общий исходный вход до дедупликации. Для каждой выборки использовано 20 000 перевыборок.']
    for lab,v in [('Разработка, прогнозы по исключённым репозиториям',dev),('Перенос, замороженная модель',s)]:
        out.append('### '+lab)
        tab=['| Метод | Попадания | Межзапросно сохранено токенов | Осталось кодировать | Выигрыш, п.п. [95% ДИ] |','|---|---:|---:|---:|---:|']
        for k in names:
            z=v['arms'][k];tab.append(f"| {names[k]} | {n(z['hits'])} | {n(z['saved'])} | {n(z['net'])} | {'—' if k=='graph' else ci(z)} |")
        out.append('\n'.join(tab))
    out+=['На разработческих фолдах преимущество над «частота × стоимость» положительно в четырёх из пяти случаев; в одном фолде потрачено на 1 942 токена больше. Сводный разработческий интервал к локальной модели содержит ноль. Результат на переносе не обеспечивает универсального улучшения на отдельном репозитории. [Фолды и макросредние](results.json)',
      '## Из какого признака возникает эффект',
      f"Первичная абляция вместе удаляла факт открытия файла и сведения о соседних фрагментах. После её измерения зарегистрировали отдельную проверку этих двух источников. На переносе полная модель против local + open даёт {ci(ab['R49']['graph-open'])} п.п. Добавление соседей без индикатора открытия к local даёт {ci(ab['R49']['neighbors-local'])} п.п. Вклад открытия поверх соседства {ci(ab['R49']['graph-neighbors'])} п.п. На development разность полного метода к local + open {ci(ab['R48']['graph-open'])} п.п. Результат поддерживает интерпретацию через состав соседства, однако эта проверка выполнена на уже открытой панели. [Дополнительная регистрация](ABLATION_RU.md) · [Все результаты абляций](ablation-results.json)",
      '## Затраты и ограничения',
      f"Сериализованы и восстановлены из байтов 968 состояний метаданных. Максимальный суммарный объём — {n(res['peak_total'])} байта, включая 31 вектор float32 по 16 384 байта, 64 байта метаданных на узел и 256 байт заголовка с коэффициентами регрессии. После восстановления записи и модели решения совпали. На панели переноса медиана выбора после выдачи: граф {res['panels']['R49']['graph']['median_ms']:.3f} мс, local {res['panels']['R49']['local']['median_ms']:.3f} мс, «частота × стоимость» {res['panels']['R49']['proposed']['median_ms']:.3f} мс. Это клиентская работа CPU в памяти, без кодировщика и дисковой сериализации, по три замера в чередующемся порядке. Временные индексы текущего пакета освобождаются после обновления. [Память и время](resources.json)",
      'Результат алгоритма характеризует отбор уже рассчитанных векторов на последовательности архивных состояний. Он не измеряет вероятность решения issue, качество свободного агентного поиска или сквозное время. Пулы кандидатов, формирование observed_by_state, небольшая глубина многих линий и повторное использование Cal500 ограничивают переносимость. Координаты и идентификатор наблюдённого пути читаются из текущей структурированной выдачи, весь репозиторий индексировать не требуется. Независимый скалярный верификатор воспроизвёл все 1 936 прогнозов. Для пограничных равных приоритетов записано вычислительное уточнение; после него первичные числовые эффекты сохранились. [Воспроизведение](REPRODUCE_RU.md) · [Уточнение численной точности](NUMERICS_RU.md)']
    doc='\n\n'.join(out)+'\n'
    (D/'REPORT_RU.md').write_text(doc,encoding='utf-8')
if __name__=='__main__':main()

